'use client';

import { useState, useEffect } from 'react';
import { Task, TaskFilter as TaskFilterType } from './types'; 
import { useTasks } from './hooks/useTasks'; 
import { TaskForm } from './TaskForm';
import { TaskStats } from './TaskStats';
import TaskFilter from './TaskFilter';
import { MoonIcon, SunIcon } from './icons'; 
import { TaskList } from '../TaskList';

export const TaskManager = () => {
  // --- Global State ---
  const [darkMode, setDarkMode] = useState(false);
  const [filter, setFilter] = useState<TaskFilterType>('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [isMounted, setIsMounted] = useState(false);

  // --- Task State Management via Hook ---
  const {
    tasks,
    isLoading, 
    addTask,
    editTask,
    deleteTask,
    toggleComplete,
    reorderTasks,
  } = useTasks();

  // Initialize dark mode from system preferences
  useEffect(() => {
    setIsMounted(true);
    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
    setDarkMode(mediaQuery.matches);

    const handler = (e: MediaQueryListEvent) => setDarkMode(e.matches);
    mediaQuery.addEventListener('change', handler);

    return () => mediaQuery.removeEventListener('change', handler);
  }, []);

  const toggleDarkMode = () => setDarkMode(!darkMode);
  
  // Task filtering implementation (before passing to TaskList)
  const filteredTasks = tasks.filter(task => {
    // 1. Filter by search term
    const matchesSearch = task.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          task.description?.toLowerCase().includes(searchTerm.toLowerCase());
    
    if (!matchesSearch) return false;

    // 2. Filter by status
    if (filter === 'all') return true;
    if (filter === 'active') return !task.completed;
    if (filter === 'completed') return task.completed;
    
    return true;
  });

  // --- Loading State and Mount Check ---
  if (!isMounted || isLoading) {
    return (
      <div className="flex justify-center items-center min-h-screen">
        <p className={`text-xl font-semibold ${darkMode ? 'text-gray-400' : 'text-gray-600'}`}>
          Loading tasks from API...
        </p>
      </div>
    );
  }

  return (
    <div className={`min-h-screen transition-colors duration-300 ${darkMode ? 'bg-gray-900 text-gray-200' : 'bg-gray-50 text-gray-800'}`}>
      {/* Dark mode toggle */}
      <button
        onClick={toggleDarkMode}
        className={`fixed top-6 right-6 p-2 rounded-full z-50 transition-colors ${
          darkMode 
            ? 'bg-gray-700 hover:bg-gray-600 text-yellow-300' 
            : 'bg-gray-200 hover:bg-gray-300 text-blue-900'
        }`}
        aria-label={darkMode ? 'Switch to light mode' : 'Switch to dark mode'}
      >
        {darkMode ? <SunIcon className="h-6 w-6" /> : <MoonIcon className="h-6 w-6" />}
      </button>

      <div className="container mx-auto px-5 py-10 max-w-8xl relative">
        {/* Header */}
        <header className="text-center mb-10">
          <h1 className={`text-6xl md:text-5xl font-bold mb-5 bg-clip-text text-transparent ${
            darkMode 
              ? 'bg-gradient-to-r from-blue-400 to-purple-400' 
              : 'bg-gradient-to-r from-blue-600 to-purple-600'
          }`}>
            Task Manager
          </h1>
        </header>

        {/* Stats */}
        <TaskStats tasks={tasks} darkMode={darkMode} />

        {/* Add Task Form */}
        <TaskForm 
          darkMode={darkMode}
          onAddTask={addTask}
        />

        {/* Filter and Search */}
        <TaskFilter
          darkMode={darkMode}
          filter={filter}
          setFilter={setFilter}
          searchTerm={searchTerm}
          setSearchTerm={setSearchTerm}
          tasks={tasks}
        />

        {/* Task List */}
        <div className={`mt-6 rounded-lg overflow-hidden shadow-lg ${
          darkMode ? 'bg-gray-800' : 'bg-white'
        }`}>
          <TaskList
            tasks={filteredTasks}
            toggleComplete={toggleComplete}
            deleteTask={deleteTask}
            editTask={editTask}
            setEditingTask={setEditingTask}
            reorderTasks={reorderTasks}
            darkMode={darkMode}
          />
        </div>

        {/* Edit Task Modal */}
        {editingTask && (
          <div className={`fixed inset-0 z-50 flex items-center justify-center p-4 ${
            darkMode ? 'bg-black/80' : 'bg-black/50'
          }`}>
            <div className={`relative w-full max-w-md rounded-xl shadow-xl ${
              darkMode 
                ? 'bg-gray-800 border border-gray-700' 
                : 'bg-white'
            }`}>
              <div className="p-6">
                <h2 className="text-xl font-semibold mb-4">
                  Edit Task
                </h2>
                {/* Edit form will go here */}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};